// Checkout conversion module - ensures paid events are recorded
const axios = require('axios');

module.exports = async function processCheckout(sessionId, amount, currency) {
  try {
    // Simulate payment processing
    const paymentResult = { success: true, transactionId: 'txn_' + Date.now() };
    if (!paymentResult.success) {
      throw new Error('Payment failed');
    }
    // Record paid event
    await axios.post('http://localhost:4000/api/events', {
      type: 'paid',
      sessionId,
      amount,
      currency,
      timestamp: new Date().toISOString()
    });
    return { status: 'completed', transactionId: paymentResult.transactionId };
  } catch (err) {
    console.error('Checkout conversion error:', err.message);
    return { status: 'failed', error: err.message };
  }
};
